"""Rolling statistics for a stream of GPU power readings (watts)."""
from collections import deque
from dataclasses import dataclass, field


@dataclass
class Reading:
    t: float      # seconds since start
    watts: float


@dataclass
class RollingStats:
    window: int = 8
    _buf: deque = field(default_factory=deque)
    _total: float = 0.0

    def add(self, r: Reading) -> None:
        self._buf.append(r)
        self._total += r.watts
        if len(self._buf) > self.window:
            old = self._buf.popleft()
            self._total -= old.watts

    def mean(self) -> float:
        if not self._buf:
            return 0.0
        return self._total / len(self._buf)

    def peak(self) -> float:
        return max((r.watts for r in self._buf), default=0.0)


def moving_average(values: list[float], k: int) -> list[float]:
    """Mean of every run of k consecutive values, in order."""
    if k <= 0:
        raise ValueError("k must be positive")
    out = []
    for i in range(len(values) - k + 1):
        out.append(sum(values[i:i + k]) / k)
    return out


def energy_joules(readings: list[Reading]) -> float:
    """Trapezoid rule over the readings."""
    total = 0.0
    for a, b in zip(readings, readings[1:]):
        total += (b.t - a.t) * (a.watts + b.watts) / 2
    return total


def summarize(readings: list[Reading], window: int = 8) -> dict:
    stats = RollingStats(window=window)
    for r in readings:
        stats.add(r)
    return {
        "samples": len(readings),
        "last_mean_w": round(stats.mean(), 1),
        "last_peak_w": round(stats.peak(), 1),
        "energy_j": round(energy_joules(readings), 1),
        "smoothed": moving_average([r.watts for r in readings], 4),

